insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-kursi', 'morning', 'آية الكرسي', null, '[{"surah":2,"from":255,"to":255}]'::jsonb, 1, 'رواه النسائي في السنن الكبرى والحاكم، وصححه الألباني في صحيح الترغيب والترهيب', null, null, 1) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-quls', 'morning', 'سورة الإخلاص والمعوذتان', null, '[{"surah":112,"from":1,"to":4},{"surah":113,"from":1,"to":5},{"surah":114,"from":1,"to":6}]'::jsonb, 3, 'رواه أبو داود (5082) والترمذي (3575)', '«تكفيك من كل شيء»', null, 2) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-asbahna', 'morning', null, 'أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ', null, 1, 'رواه مسلم (2723)', null, null, 3) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-bika', 'morning', null, 'اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ', null, 1, 'رواه الترمذي (3391)', null, null, 4) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-sayyid', 'morning', 'سيد الاستغفار', 'اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', null, 1, 'رواه البخاري (6306)', '«ومن قالها من النهار موقنًا بها فمات من يومه قبل أن يمسي فهو من أهل الجنة»', null, 5) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-afini', 'morning', null, 'اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ', null, 3, 'رواه أبو داود (5090)', null, null, 6) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-afw', 'morning', null, 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي', null, 1, 'رواه أبو داود (5074) وابن ماجه (3871)', null, null, 7) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-alim', 'morning', null, 'اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءًا، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ', null, 1, 'رواه الترمذي (3392) وأبو داود (5067)', null, null, 8) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-bismillah', 'morning', null, 'بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ', null, 3, 'رواه أبو داود (5088) والترمذي (3388)', null, null, 9) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-raditu', 'morning', null, 'رَضِيتُ بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا', null, 3, 'رواه الترمذي (3389) وأبو داود (5072)', null, null, 10) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-hayy', 'morning', null, 'يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ، وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ', null, 1, 'رواه الحاكم وصححه، وحسّنه الألباني في صحيح الترغيب والترهيب', null, null, 11) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-fitra', 'morning', null, 'أَصْبَحْنَا عَلَى فِطْرَةِ الْإِسْلَامِ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ', null, 1, 'رواه أحمد (15360)', null, null, 12) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-juwayriya', 'morning', null, 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ', null, 3, 'رواه مسلم (2726)', null, null, 13) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-ilm', 'morning', null, 'اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا', null, 1, 'رواه ابن ماجه (925)', null, 'كان النبي ﷺ يقوله إذا صلى الصبح حين يسلّم', 14) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-tahlil', 'morning', null, 'لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', null, 100, 'رواه البخاري (3293) ومسلم (2691)', null, 'ورد في الحديث: «من قال ... في يوم مائة مرة»', 15) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-subhan', 'morning', null, 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ', null, 100, 'رواه مسلم (2692)', null, null, 16) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('m-istighfar', 'morning', null, 'أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ', null, 100, 'رواه البخاري (6307) ومسلم (2702)', null, 'في صحيح مسلم: «فإني أتوب في اليوم إليه مائة مرة»', 17) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('e-kursi', 'evening', 'آية الكرسي', null, '[{"surah":2,"from":255,"to":255}]'::jsonb, 1, 'رواه النسائي في السنن الكبرى والحاكم، وصححه الألباني في صحيح الترغيب والترهيب', null, null, 1) on conflict (id) do nothing;
