insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('e-quls', 'evening', 'سورة الإخلاص والمعوذتان', null, '[{"surah":112,"from":1,"to":4},{"surah":113,"from":1,"to":5},{"surah":114,"from":1,"to":6}]'::jsonb, 3, 'رواه أبو داود (5082) والترمذي (3575)', '«تكفيك من كل شيء»', null, 3) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('e-amsayna', 'evening', null, 'أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ', null, 1, 'رواه مسلم (2723)', null, null, 4) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('e-bika', 'evening', null, 'اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ الْمَصِيرُ', null, 1, 'رواه الترمذي (3391)', null, null, 5) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('e-sayyid', 'evening', 'سيد الاستغفار', 'اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', null, 1, 'رواه البخاري (6306)', '«ومن قالها من الليل وهو موقن بها فمات قبل أن يصبح فهو من أهل الجنة»', null, 6) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('e-afini', 'evening', null, 'اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ', null, 3, 'رواه أبو داود (5090)', null, null, 7) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('e-afw', 'evening', null, 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي', null, 1, 'رواه أبو داود (5074) وابن ماجه (3871)', null, null, 8) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('e-alim', 'evening', null, 'اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءًا، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ', null, 1, 'رواه الترمذي (3392) وأبو داود (5067)', null, null, 9) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('e-bismillah', 'evening', null, 'بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ', null, 3, 'رواه أبو داود (5088) والترمذي (3388)', null, null, 10) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('e-raditu', 'evening', null, 'رَضِيتُ بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا', null, 3, 'رواه الترمذي (3389) وأبو داود (5072)', null, null, 11) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('e-hayy', 'evening', null, 'يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ، وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ', null, 1, 'رواه الحاكم وصححه، وحسّنه الألباني في صحيح الترغيب والترهيب', null, null, 12) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('e-fitra', 'evening', null, 'أَمْسَيْنَا عَلَى فِطْرَةِ الْإِسْلَامِ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ', null, 1, 'رواه أحمد (15360)', null, null, 13) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('e-kalimat', 'evening', null, 'أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ', null, 3, 'رواه مسلم (2709)', null, null, 14) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('e-subhan', 'evening', null, 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ', null, 100, 'رواه مسلم (2692)', '«من قال حين يصبح وحين يمسي: سبحان الله وبحمده مائة مرة، لم يأت أحد يوم القيامة بأفضل مما جاء به إلا أحد قال مثل ما قال أو زاد عليه»', null, 15) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('p-istighfar', 'after-prayer', null, 'أَسْتَغْفِرُ اللَّهَ، أَسْتَغْفِرُ اللَّهَ، أَسْتَغْفِرُ اللَّهَ. اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ', null, 1, 'رواه مسلم (591)', null, null, 1) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('p-mani', 'after-prayer', null, 'لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ', null, 1, 'رواه البخاري (844) ومسلم (593)', null, null, 2) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('p-zubayr', 'after-prayer', null, 'لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، لَا إِلَهَ إِلَّا اللَّهُ، وَلَا نَعْبُدُ إِلَّا إِيَّاهُ، لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ، لَا إِلَهَ إِلَّا اللَّهُ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ', null, 1, 'رواه مسلم (594)', null, null, 3) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('p-tasbih', 'after-prayer', null, 'سُبْحَانَ اللَّهِ', null, 33, 'رواه مسلم (597)', null, null, 4) on conflict (id) do nothing;
