insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('p-tamam', 'after-prayer', null, 'لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', null, 1, 'رواه مسلم (597)', null, 'تمام المائة', 7) on conflict (id) do nothing;
