insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('p-ainni', 'after-prayer', null, 'اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ', null, 1, 'رواه أبو داود (1522) والنسائي (1303)', null, null, 10) on conflict (id) do nothing;
