insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('s-quls', 'sleep', 'سورة الإخلاص والمعوذتان', null, '[{"surah":112,"from":1,"to":4},{"surah":113,"from":1,"to":5},{"surah":114,"from":1,"to":6}]'::jsonb, 3, 'رواه البخاري (5017)', null, 'يجمع كفيه ثم ينفث فيهما ويقرأ، ثم يمسح بهما ما استطاع من جسده، يفعل ذلك ثلاث مرات', 2) on conflict (id) do nothing;
