insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('s-wadatu', 'sleep', null, 'بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، إِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ', null, 1, 'رواه البخاري (6320) ومسلم (2714)', null, null, 5) on conflict (id) do nothing;
