insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('s-aslamtu', 'sleep', null, 'اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ', null, 1, 'رواه البخاري (6313) ومسلم (2710)', null, 'يجعله آخر ما يقول قبل النوم', 10) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('w-ahyana', 'waking', null, 'الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ', null, 1, 'رواه البخاري (6312)', null, null, 1) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('w-afani', 'waking', null, 'الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لِي بِذِكْرِهِ', null, 1, 'رواه الترمذي (3401)', null, null, 2) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('d-atina', 'duas', null, null, '[{"surah":2,"from":201,"to":201}]'::jsonb, 1, 'كان أكثر دعاء النبي ﷺ — رواه البخاري (6389) ومسلم (2690)', null, null, 1) on conflict (id) do nothing;
