insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('d-dhunnun', 'duas', 'دعوة ذي النون', null, '[{"surah":21,"from":87,"to":87}]'::jsonb, 1, 'القرآن الكريم — سورة الأنبياء؛ وفي فضلها حديث رواه الترمذي (3505)', null, 'موضع الدعاء في خاتمة الآية', 4) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('d-muqallib', 'duas', null, 'يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ', null, 1, 'رواه الترمذي (2140)', null, null, 5) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('d-hamm', 'duas', null, 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ', null, 1, 'رواه البخاري (6369)', null, null, 6) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('d-huda', 'duas', null, 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى، وَالْعَفَافَ وَالْغِنَى', null, 1, 'رواه مسلم (2721)', null, null, 7) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('d-zalamtu', 'duas', null, 'اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ', null, 1, 'رواه البخاري (834) ومسلم (2705)', null, null, 8) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('d-kalimatan', 'duas', null, 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ', null, 1, 'رواه البخاري (6406) ومسلم (2694)', '«كلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن»', null, 9) on conflict (id) do nothing;
insert into public.adhkar (id, category_id, title, body, quran, repeat, source_text, virtue, note, sort) values ('d-hawqala', 'duas', null, 'لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ', null, 1, 'رواه البخاري (4205) ومسلم (2704)', '«كنز من كنوز الجنة»', null, 10) on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-01', 13, 28, 28, 'ويهدي الذين تسكن قلوبهم بتوحيد الله وذكره فتطمئن، ألا بطاعة الله وذكره وثوابه تسكن القلوب وتستأنس', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'متى شعرتَ آخر مرة بسكينة حقيقية بعد ذكر الله؟ وما الذي يمنعك من تكرار تلك اللحظة؟', 'خصّص اليوم خمس دقائق هادئة لذكر الله بعيدًا عن الهاتف.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-02', 2, 152, 152, 'أمر تعالى المؤمنين بذكره، ووعد عليه أفضل الجزاء، وهو الثناء في الملأ الأعلى على مَنْ ذكره، وخصوني -أيها المؤمنون- بالشكر قولا وعملا ولا تجحدوا نعمي عليكم', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'ما النعمة التي اعتدتَ عليها حتى نسيتَ أن تشكر الله عليها؟', 'اكتب ثلاث نعم تشكر الله عليها اليوم، واذكر واحدة منها بلسانك.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-03', 2, 186, 186, 'وإذا سألك -أيها النبي- عبادي عني فقل لهم: إني قريب منهم، أُجيب دعوة الداعي إذا دعاني، فليطيعوني فيما أمرتهم به ونهيتهم عنه، وليؤمنوا بي، لعلهم يهتدون إلى مصالح دينهم ودنياهم. وفي هذه الآية إخبار منه سبحانه عن قربه من عباده، القرب اللائق بجلاله', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'لو استحضرتَ قرب الله منك الآن، فبماذا ستدعوه؟', 'اختر دعوة واحدة تهمّك، وادعُ بها في سجودك اليوم.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-04', 94, 5, 6, 'فلا يثنك أذى أعدائك عن نشر الرسالة؛ فإن مع الضيق فرجًا، إن مع الضيق فرجًا', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'ما الضيق الذي تمرّ به الآن؟ وكيف يغيّر وعد الله باليسر نظرتك إليه؟', 'اكتب أمرًا صعبًا تمر به، وبجانبه بابًا واحدًا من الفرج يمكنك أن تسعى إليه.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-05', 39, 53, 53, 'قل -أيها الرسول- لعبادي الذين تمادَوا في المعاصي، وأسرفوا على أنفسهم بإتيان ما تدعوهم إليه نفوسهم من الذنوب: لا تَيْئسوا من رحمة الله؛ لكثرة ذنوبكم، إن الله يغفر الذنوب جميعًا لمن تاب منها ورجع عنها مهما كانت، إنه هو الغفور لذنوب التائبين من عباده، الرحيم بهم', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'هل يحول بينك وبين الرجوع إلى الله شعورٌ باليأس؟ كيف تقرأ هذه الآية في ضوء ذلك؟', 'جدّد التوبة اليوم باستغفار صادق، ولو بكلمات قليلة.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-06', 2, 153, 153, 'يا أيها المؤمنون اطلبوا العون من الله في كل أموركم: بالصبر على النوائب والمصائب، وترك المعاصي والذنوب، والصبر على الطاعات والقربات، والصلاة التي تطمئن بها النفس، وتنهى عن الفحشاء والمنكر. إن الله مع الصابرين بعونه وتوفيقه وتسديده. وفي الآية: إثبات معيَّة الله الخاصة بالمؤمنين، المقتضية لما سلف ذكره؛ أما المعية العامة، المقتضية للعلم والإحاطة فهي لجميع الخلق', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'في أي أمر تحتاج اليوم أن تستعين بالله بالصبر والصلاة؟', 'أدِّ صلاتك القادمة بتأنٍّ، واطلب من الله العون على ما يشغلك.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-07', 54, 17, 17, 'ولقد سَهَّلْنا لفظ القرآن للتلاوة والحفظ، ومعانيه للفهم والتدبر، لمن أراد أن يتذكر ويعتبر، فهل من متعظ به؟', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'ما الذي يجعلك تؤجل صحبة القرآن مع أن الله يسّره للذكر؟', 'اقرأ اليوم ولو صفحة واحدة بتمهّل وتدبّر.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-08', 16, 97, 97, 'مَن عمل عملا صالحًا ذكرًا كان أم أنثى، وهو مؤمن بالله ورسوله، فلنحيينه في الدنيا حياة سعيدة مطمئنة، ولو كان قليل المال، ولنجزينَّهم في الآخرة ثوابهم بأحسن ما عملوا في الدنيا', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'ما معنى «الحياة الطيبة» في يومك أنت، بعيدًا عن كثرة المال؟', 'قدّم اليوم عملًا صالحًا صغيرًا لا يعلمه أحد غيرك.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-09', 12, 87, 87, 'قال يعقوب: يا أبنائي عودوا إلى "مصر" فاستقصوا أخبار يوسف وأخيه، ولا تقطعوا رجاءكم من رحمة الله، إنه لا يقطع الرجاء من رحمة الله إلا الجاحدون لقدرته، الكافرون به', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'ما الأمر الذي كدتَ تفقد فيه الرجاء؟ وكيف يعيد إليك يعقوب عليه السلام الأمل؟', 'ادعُ الله اليوم في أمرٍ ظننتَه بعيدًا، بيقين وحسن ظن.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-10', 25, 63, 63, 'وعباد الرحمن الصالحون يمشون على الأرض بسكينة متواضعين، وإذا خاطبهم الجهلة السفهاء بالأذى أجابوهم بالمعروف من القول، وخاطبوهم خطابًا يَسْلَمون فيه من الإثم، ومن مقابلة الجاهل بجهله', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'كيف يكون ردّك عادةً حين يُساء إليك؟ وما الذي تريد أن تغيّره؟', 'تدرّب اليوم على الرد الهادئ في موقف واحد على الأقل.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-11', 38, 29, 29, 'هذا الموحى به إليك -أيها الرسول- كتاب أنزلناه إليك مبارك؛ ليتفكروا في آياته، ويعملوا بهداياته ودلالاته، وليتذكر أصحاب العقول السليمة ما كلفهم الله به', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'ما آخر آية توقفتَ عندها متأملًا؟ وماذا تعلّمت منها؟', 'اختر آية من وردك اليوم واكتب ما فهمته منها في سطر.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-12', 14, 7, 7, 'وقال لهم موسى: واذكروا حين أعلم ربكم إعلامًا مؤكَّدًا: لئن شكرتموه على نعمه ليزيدنكم من فضله، ولئن جحدتم نعمة الله ليعذبنَّكم عذابًا شديدًا', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'كيف يمكن أن يكون الشكر بالعمل لا باللسان فقط؟', 'استعمل نعمة من نعم الله اليوم في طاعة أو نفع لغيرك.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-13', 50, 16, 16, 'ولقد خلقنا الإنسان، ونعلم ما تُحَدِّث به نفسه، ونحن أقرب إليه من حبل الوريد (وهو عِرْق في العنق متصل بالقلب)', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'كيف يتغيّر حديثك مع نفسك حين تستحضر أن الله يعلم ما توسوس به؟', 'راقب خواطرك اليوم، واستبدل خاطرًا سلبيًا بذكر أو دعاء.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-14', 8, 2, 2, 'إنما المؤمنون بالله حقًا هم الذين إذا ذُكِر الله فزعت قلوبهم، وإذا تليت عليهم آيات القرآن زادتهم إيمانًا مع إيمانهم، لتدبرهم لمعانيه وعلى الله تعالى يتوكلون، فلا يرجون غيره، ولا يرهبون سواه', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'متى زادتك آيةٌ إيمانًا؟ وما الذي كان مختلفًا في تلك القراءة؟', 'استمع إلى تلاوة خاشعة اليوم وأنت متفرغ القلب.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-15', 3, 191, 191, 'الذين يذكرون الله في جميع أحوالهم: قيامًا وقعودًا وعلى جنوبهم، وهم يتدبرون في خلق السموات والأرض، قائلين: يا ربنا ما أوجدت هذا الخلق عبثًا، فأنت منزَّه عن ذلك، فاصْرِف عنا عذاب النار', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'ماذا ترى من آيات الله في الطريق الذي تسلكه كل يوم؟', 'تأمّل السماء أو منظرًا من الطبيعة دقيقتين، واذكر الله.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-16', 2, 201, 201, 'ومن الناس فريق مؤمن يقول في دعائه: ربنا آتنا في الدنيا عافية ورزقًا وعلمًا نافعًا، وعملا صالحًا، وغير ذلك من أمور الدين والدنيا، وفي الآخرة الجنة، واصرف عنَّا عذاب النار. وهذا الدعاء من أجمع الأدعية، ولهذا كان أكثر دعاء النبي صلى الله عليه وسلم، كما ثبت في الصحيحين', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'لماذا كان هذا الدعاء من أجمع الأدعية في رأيك؟', 'احفظ هذا الدعاء إن لم تكن تحفظه، وادعُ به اليوم.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-17', 29, 69, 69, 'والمؤمنون الذين جاهدوا أعداء الله، والنفس، والشيطان، وصبروا على الفتن والأذى في سبيل الله، سيهديهم الله سبل الخير، ويثبتهم على الصراط المستقيم، ومَن هذه صفته فهو محسن إلى نفسه وإلى غيره. وإن الله سبحانه وتعالى لمع مَن أحسن مِن خَلْقِه بالنصرة والتأييد والحفظ والهداية', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'ما المجاهدة الصغيرة التي تحتاجها نفسك اليوم لتثبت على الخير؟', 'اختر عادة واحدة تريد تحسينها، وابدأ فيها بخطوة صغيرة اليوم.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-18', 57, 16, 16, 'ألم يحن الوقت للذين صدَّقوا الله ورسوله واتَّبَعوا هديه، أن تلين قلوبهم عند ذكر الله وسماع القرآن، ولا يكونوا في قسوة القلوب كالذين أوتوا الكتاب من قبلهم- من اليهود والنصارى- الذين طال عليهم الزمان فبدَّلوا كلام الله، فقست قلوبهم، وكثير منهم خارجون عن طاعة الله؟ وفي الآية الحث على الرقة والخشوع لله سبحانه عند سماع ما أنزله من الكتاب والحكمة، والحذر من التشبه باليهود والنصارى، في قسوة قلوبهم، وخروجهم عن طاعة الله', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'ما الذي يرقّق قلبك عند سماع القرآن؟ وما الذي يقسّيه؟', 'ابتعد اليوم عن شيء واحد تشعر أنه يقسّي قلبك.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-19', 17, 9, 9, 'إن هذا القرآن الذي أنزلناه على عبدنا محمد يرشد الناس إلى أحسن الطرق، وهي ملة الإسلام، ويبشر المؤمنين الذين يعملون بما أمرهم الله به، وينتهون عمَّا نهاهم عنه، بأن لهم ثوابًا عظيمًا، وأن الذين لا يصدقون بالدار الآخرة وما فيها من الجزاء أعددنا لهم عذابًا موجعًا في النار', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'في أي جانب من حياتك تحتاج إلى هداية القرآن الآن؟', 'ابحث عن آية تتعلق بأمر يشغلك، واقرأ معناها في تفسير معتمد.', 'published') on conflict (id) do nothing;
insert into public.oasis_moments (id, surah, ayah_from, ayah_to, meaning, meaning_source, reflection, action, status) values ('moment-20', 49, 13, 13, 'يا أيها الناس إنَّا خلقناكم من أب واحد هو آدم، وأُم واحدة هي حواء، فلا تفاضل بينكم في النسب، وجعلناكم بالتناسل شعوبًا وقبائل متعددة؛ ليعرف بعضكم بعضًا، إن أكرمكم عند الله أشدكم اتقاءً له. إن الله عليم بالمتقين، خبير بهم', 'التفسير الميسر — نخبة من العلماء، مجمع الملك فهد لطباعة المصحف الشريف', 'كيف تغيّر هذه الآية معيارك في تقدير الناس؟', 'أحسن اليوم إلى شخص قد لا يلتفت إليه أحد.', 'published') on conflict (id) do nothing;
insert into public.learning_paths (id, title, description, goals, level, color, sort) values ('tajweed-basics', 'أساسيات التجويد', 'مدخل مبسّط إلى أهم أحكام التجويد التي يحتاجها كل قارئ للقرآن الكريم.', array['فهم معنى التجويد وأهميته', 'معرفة أحكام النون الساكنة والتنوين', 'معرفة أحكام الميم الساكنة', 'التمييز بين أنواع المدود الأساسية']::text[], 'مبتدئ', 'olive', 0) on conflict (id) do nothing;
insert into public.lessons (path_id, id, title, summary, minutes, body, sources, sort) values ('tajweed-basics', 'what-is-tajweed', 'ما التجويد ولماذا نتعلّمه؟', 'تعريف التجويد وثمرته ومكانته عند القارئ.', 5, 'التجويد في اللغة: التحسين والإتقان. وفي الاصطلاح: إخراج كل حرف من مخرجه، مع إعطائه حقّه ومستحقّه من الصفات والأحكام.
insert into public.lessons (path_id, id, title, summary, minutes, body, sources, sort) values ('tajweed-basics', 'istiadha-basmala', 'الاستعاذة والبسملة', 'متى نستعيذ ومتى نبسمل عند بدء التلاوة.', 4, 'يُشرع للقارئ أن يستعيذ بالله من الشيطان الرجيم عند ابتداء القراءة، وصيغتها المشهورة: «أعوذ بالله من الشيطان الرجيم».
