insert into public.lessons (path_id, id, title, summary, minutes, body, sources, sort) values ('tajweed-basics', 'madd-basics', 'مدخل إلى المدود', 'المد الطبيعي وأشهر أنواع المد الفرعي ومقاديرها في رواية حفص.', 7, 'حروف المد ثلاثة: الألف الساكنة المفتوح ما قبلها، والواو الساكنة المضموم ما قبلها، والياء الساكنة المكسور ما قبلها.
